R["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class SlowIo\n    {\n        private readonly int[] _delays;\n        public SlowIo(params int[] delaysMs) => _delays = delaysMs;\n        public System.Collections.Generic.List<(int Step, int Tick)> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step, System.Threading.CancellationToken ct = default)\n        {\n            await System.Threading.Tasks.Task.Delay(_delays[step % _delays.Length], ct);\n            Log.Add((step, System.Environment.TickCount));\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(SlowIo io, System.Threading.CancellationToken ct = default)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step, ct);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(SlowIo io, System.Threading.CancellationToken ct = default)\n    {\n        var t0 = io.FetchAsync(0, ct);\n        var t1 = io.FetchAsync(1, ct);\n        var t2 = io.FetchAsync(2, ct);\n        int[] all = await System.Threading.Tasks.Task.WhenAll(t0, t1, t2);\n        return all[0] + all[1] + all[2];\n    }\n}\n";
W["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class SlowIo\n    {\n        private readonly int[] _delays;\n        public SlowIo(params int[] delaysMs) => _delays = delaysMs;\n        public System.Collections.Generic.List<(int Step, int Tick)> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step, System.Threading.CancellationToken ct = default)\n        {\n            await System.Threading.Tasks.Task.Delay(_delays[step % _delays.Length], ct);\n            Log.Add((step, System.Environment.TickCount));\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(SlowIo io, System.Threading.CancellationToken ct = default)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step, ct);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(SlowIo io, System.Threading.CancellationToken ct = default)\n    {\n        // near-miss: awaits the first fetch BEFORE starting the next two \u2014\n        // the \"concurrent\" method is actually sequential and the overlap test\n        // fails\n        int a = await io.FetchAsync(0);\n        var t1 = io.FetchAsync(1);\n        var t2 = io.FetchAsync(2);\n        int[] rest = await System.Threading.Tasks.Task.WhenAll(t1, t2);\n        return a + rest[0] + rest[1];\n    }\n}\n";
R["csi-p9-blocked-debug"] = "public class Solution\n{\n    public sealed class SingleThreadScheduler\n    {\n        public System.Threading.Tasks.Task<T> RunAsync<T>(Func<T> work)\n        {\n            var tcs = new System.Threading.Tasks.TaskCompletionSource<T>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);\n            System.Threading.ThreadPool.QueueUserWorkItem(_ =>\n            {\n                try { tcs.SetResult(work()); }\n                catch (Exception ex) { tcs.SetException(ex); }\n            });\n            return tcs.Task;\n        }\n    }\n\n    public sealed class Handler\n    {\n        public async System.Threading.Tasks.Task<string> HandleAsync(SingleThreadScheduler sched)\n        {\n            string data = await sched.RunAsync(() => \"ok\");\n            return data + \"!\";\n        }\n    }\n}\n";
W["csi-p9-blocked-debug"] = "public class Solution\n{\n    public sealed class SingleThreadScheduler\n    {\n        public System.Threading.Tasks.Task<T> RunAsync<T>(Func<T> work)\n        {\n            var tcs = new System.Threading.Tasks.TaskCompletionSource<T>(System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);\n            System.Threading.ThreadPool.QueueUserWorkItem(_ =>\n            {\n                try { tcs.SetResult(work()); }\n                catch (Exception ex) { tcs.SetException(ex); }\n            });\n            return tcs.Task;\n        }\n    }\n\n    public sealed class Handler\n    {\n        // near-miss: .Result blocks the continuation loop \u2014 the awaited fetch\n        // can never complete because its continuation is queued behind the\n        // blocked caller\n        public System.Threading.Tasks.Task<string> HandleAsync(SingleThreadScheduler sched)\n        {\n            return System.Threading.Tasks.Task.FromResult(sched.RunAsync(() => \"ok\").Result + \"!\");\n        }\n    }\n}\n";
R["csi-p9-cancel-token"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<int> ProcessAsync(\n        System.Collections.Generic.IEnumerable<int> items,\n        Func<int, System.Threading.Tasks.Task> work,\n        System.Threading.CancellationToken ct)\n    {\n        int done = 0;\n        foreach (int item in items)\n        {\n            ct.ThrowIfCancellationRequested();\n            await work(item);\n            done++;\n        }\n        return done;\n    }\n}\n";
W["csi-p9-cancel-token"] = "public class Solution\n{\n    // near-miss: checks cancellation only AFTER the work \u2014 item 3 runs and\n    // the cancel-promptly test sees ran == 3, failing the == 2 assertion\n    public static async System.Threading.Tasks.Task<int> ProcessAsync(\n        System.Collections.Generic.IEnumerable<int> items,\n        Func<int, System.Threading.Tasks.Task> work,\n        System.Threading.CancellationToken ct)\n    {\n        int done = 0;\n        foreach (int item in items)\n        {\n            await work(item);\n            done++;\n            ct.ThrowIfCancellationRequested();\n        }\n        return done;\n    }\n}\n";
R["csi-p9-timeout"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<string> WithTimeout(\n        System.Threading.Tasks.Task<string> work, int timeoutMs)\n    {\n        var done = await System.Threading.Tasks.Task.WhenAny(\n            work, System.Threading.Tasks.Task.Delay(timeoutMs));\n        if (done != work)\n            throw new System.TimeoutException(\"operation timed out\");\n        return await work;\n    }\n}\n";
W["csi-p9-timeout"] = "public class Solution\n{\n    // near-miss: awaits the work FIRST \u2014 a hung task never returns and the\n    // timeout path is unreachable; the slow-path test hangs instead of\n    // throwing TimeoutException\n    public static async System.Threading.Tasks.Task<string> WithTimeout(\n        System.Threading.Tasks.Task<string> work, int timeoutMs)\n    {\n        string result = await work;\n        _ = System.Threading.Tasks.Task.Delay(timeoutMs);\n        return result;\n    }\n}\n";
R["csi-p9-dropped-task-debug"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task SaveAllAsync(SaveTrap trap, System.Collections.Generic.IEnumerable<string> keys)\n    {\n        var tasks = new System.Collections.Generic.List<System.Threading.Tasks.Task>();\n        foreach (string key in keys)\n            tasks.Add(trap.SaveAsync(key));\n        try\n        {\n            await System.Threading.Tasks.Task.WhenAll(tasks);\n        }\n        finally\n        {\n            foreach (var t in tasks)\n                if (t.IsFaulted) _ = t.Exception;   // observe every fault\n        }\n    }\n}\n";
W["csi-p9-dropped-task-debug"] = "public class Solution\n{\n    // near-miss: fire-and-forget \u2014 SaveAsync tasks are started but never\n    // awaited, so faults are unobserved (trap fires) and SaveAllAsync\n    // \"succeeds\" despite failing saves\n    public static System.Threading.Tasks.Task SaveAllAsync(SaveTrap trap, System.Collections.Generic.IEnumerable<string> keys)\n    {\n        foreach (string key in keys)\n            _ = trap.SaveAsync(key);\n        return System.Threading.Tasks.Task.CompletedTask;\n    }\n}\n";
R["csi-checkpoint-m9-task"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<System.Collections.Generic.List<string>> FetchAll(\n        System.Collections.Generic.IEnumerable<string> keys,\n        System.TimeSpan perCall,\n        System.Threading.CancellationToken ct)\n    {\n        ct.ThrowIfCancellationRequested();\n        var tasks = new System.Collections.Generic.Dictionary<string, System.Threading.Tasks.Task<string>>();\n        foreach (string key in keys)\n            tasks[key] = Cj.FlakyApi.FetchAsync(key, key.StartsWith(\"slow\") ? 5000 : 30, ct);\n\n        var results = new System.Collections.Generic.List<string>();\n        foreach (var (key, task) in tasks)\n        {\n            try\n            {\n                await task.WaitAsync(perCall, ct);\n                results.Add(key + \"=ok\");\n            }\n            catch (System.TimeoutException)\n            {\n                results.Add(key + \"=timeout\");\n            }\n        }\n        return results;\n    }\n\n    public static string Report(System.Collections.Generic.List<string> results)\n    {\n        return string.Join(\"|\", results\n            .Select(r => (Key: r[..r.IndexOf('=')], Text: r))\n            .OrderBy(x => x.Key, System.StringComparer.Ordinal)\n            .Select(x => x.Text));\n    }\n}\n";
W["csi-checkpoint-m9-task"] = "public class Solution\n{\n    // near-miss: awaits each fetch SEQUENTIALLY \u2014 no fan-out and the slow\n    // fetch waits its full 5s, so the <1000ms timing test fails; also no\n    // per-call timeout, so \"slow\" would never be marked timeout\n    public static async System.Threading.Tasks.Task<System.Collections.Generic.List<string>> FetchAll(\n        System.Collections.Generic.IEnumerable<string> keys,\n        System.TimeSpan perCall,\n        System.Threading.CancellationToken ct)\n    {\n        var results = new System.Collections.Generic.List<string>();\n        foreach (string key in keys)\n        {\n            try\n            {\n                await Cj.FlakyApi.FetchAsync(key, key.StartsWith(\"slow\") ? 5000 : 30, ct);\n                results.Add(key + \"=ok\");\n            }\n            catch (System.TimeoutException)\n            {\n                results.Add(key + \"=timeout\");\n            }\n        }\n        return results;\n    }\n\n    public static string Report(System.Collections.Generic.List<string> results)\n    {\n        return string.Join(\"|\", results);\n    }\n}\n";
R["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class EventIo\n    {\n        public System.Collections.Generic.List<string> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step)\n        {\n            Log.Add(\"start:\" + step);\n            await System.Threading.Tasks.Task.Yield();\n            Log.Add(\"done:\" + step);\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(EventIo io)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(EventIo io)\n    {\n        var t0 = io.FetchAsync(0);\n        var t1 = io.FetchAsync(1);\n        var t2 = io.FetchAsync(2);\n        int[] all = await System.Threading.Tasks.Task.WhenAll(t0, t1, t2);\n        return all[0] + all[1] + all[2];\n    }\n}\n";
W["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class EventIo\n    {\n        public System.Collections.Generic.List<string> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step)\n        {\n            Log.Add(\"start:\" + step);\n            await System.Threading.Tasks.Task.Yield();\n            Log.Add(\"done:\" + step);\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(EventIo io)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(EventIo io)\n    {\n        // near-miss: awaits the first fetch BEFORE starting the next two \u2014\n        // the \"concurrent\" method is actually sequential: start:0,done:0,\n        // start:1 \u2014 the overlap test fails\n        int a = await io.FetchAsync(0);\n        var t1 = io.FetchAsync(1);\n        var t2 = io.FetchAsync(2);\n        int[] rest = await System.Threading.Tasks.Task.WhenAll(t1, t2);\n        return a + rest[0] + rest[1];\n    }\n}\n";
R["csi-p9-unwrap-debug"] = "public class Solution\n{\n    public static System.Threading.Tasks.Task<string> LoadConfigAsync()\n    {\n        return System.Threading.Tasks.Task.FromException<string>(new System.InvalidOperationException(\"no config\"));\n    }\n\n    public static string GetSetting()\n    {\n        // fixed: block AND unwrap \u2014 AggregateException's InnerException keeps\n        // the caller-facing contract\n        try\n        {\n            return LoadConfigAsync().GetAwaiter().GetResult();\n        }\n        catch (System.AggregateException ag)\n        {\n            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(ag.GetBaseException()).Throw();\n            throw;   // unreachable\n        }\n    }\n}\n";
