R["csi-checkpoint-m9-task"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<System.Collections.Generic.List<string>> FetchAll(\n        System.Collections.Generic.IEnumerable<string> keys,\n        System.TimeSpan perCall,\n        System.Threading.CancellationToken ct)\n    {\n        ct.ThrowIfCancellationRequested();\n        var tasks = new System.Collections.Generic.Dictionary<string, System.Threading.Tasks.Task<string>>();\n        foreach (string key in keys)\n            tasks[key] = CjFlaky.FetchAsync(key, 30, ct);\n\n        var results = new System.Collections.Generic.List<string>();\n        foreach (var pair in tasks)\n        {\n            try\n            {\n                await pair.Value.WaitAsync(perCall, ct);\n                results.Add(pair.Key + \"=ok\");\n            }\n            catch (System.TimeoutException)\n            {\n                results.Add(pair.Key + \"=timeout\");\n            }\n        }\n        return results;\n    }\n\n    public static string Report(System.Collections.Generic.List<string> results)\n    {\n        return string.Join(\"|\", results\n            .OrderBy(r => r.Substring(0, r.IndexOf('=')))\n            .ToList());\n    }\n}\n";
W["csi-checkpoint-m9-task"] = "public class Solution\n{\n    // near-miss: awaits each fetch SEQUENTIALLY \u2014 no fan-out, and the slow\n    // fetch waits its full 5 s inside the per-call window, so the <1000 ms\n    // timing test fails\n    public static async System.Threading.Tasks.Task<System.Collections.Generic.List<string>> FetchAll(\n        System.Collections.Generic.IEnumerable<string> keys,\n        System.TimeSpan perCall,\n        System.Threading.CancellationToken ct)\n    {\n        var results = new System.Collections.Generic.List<string>();\n        foreach (string key in keys)\n        {\n            try\n            {\n                await CjFlaky.FetchAsync(key, 30, ct);\n                results.Add(key + \"=ok\");\n            }\n            catch (System.TimeoutException)\n            {\n                results.Add(key + \"=timeout\");\n            }\n        }\n        return results;\n    }\n\n    public static string Report(System.Collections.Generic.List<string> results)\n    {\n        return string.Join(\"|\", results);\n    }\n}\n";
R["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class EventIo\n    {\n        public System.Collections.Generic.List<string> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step)\n        {\n            Log.Add(\"start:\" + step);\n            await System.Threading.Tasks.Task.Yield();\n            Log.Add(\"done:\" + step);\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(EventIo io)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(EventIo io)\n    {\n        var t0 = io.FetchAsync(0);\n        var t1 = io.FetchAsync(1);\n        var t2 = io.FetchAsync(2);\n        int[] all = await System.Threading.Tasks.Task.WhenAll(t0, t1, t2);\n        return all[0] + all[1] + all[2];\n    }\n}\n";
W["csi-p9-sequence-total"] = "public class Solution\n{\n    public sealed class EventIo\n    {\n        public System.Collections.Generic.List<string> Log { get; } = new();\n\n        public async System.Threading.Tasks.Task<int> FetchAsync(int step)\n        {\n            Log.Add(\"start:\" + step);\n            await System.Threading.Tasks.Task.Yield();\n            Log.Add(\"done:\" + step);\n            return step + 1;\n        }\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumSequential(EventIo io)\n    {\n        int total = 0;\n        for (int step = 0; step < 3; step++)\n            total += await io.FetchAsync(step);\n        return total;\n    }\n\n    public static async System.Threading.Tasks.Task<int> SumConcurrent(EventIo io)\n    {\n        // near-miss: awaits the first fetch BEFORE starting the next two \u2014\n        // the \"concurrent\" method is actually sequential: start:0,done:0,\n        // start:1 \u2014 the overlap test fails\n        int a = await io.FetchAsync(0);\n        var t1 = io.FetchAsync(1);\n        var t2 = io.FetchAsync(2);\n        int[] rest = await System.Threading.Tasks.Task.WhenAll(t1, t2);\n        return a + rest[0] + rest[1];\n    }\n}\n";
