R["csi-p10-atomic-counter"] = "public class Solution\n{\n    public sealed class Counter\n    {\n        private int _count;\n\n        public void Increment()\n        {\n            CjConcurrency.Pause();   // simulated work \u2014 atomicity comes from Interlocked\n            System.Threading.Interlocked.Increment(ref _count);\n        }\n\n        public int Value => System.Threading.Volatile.Read(ref _count);\n\n        public int Drain()\n        {\n            return System.Threading.Interlocked.Exchange(ref _count, 0);\n        }\n    }\n}\n";
W["csi-p10-atomic-counter"] = "public class Solution\n{\n    public sealed class Counter\n    {\n        private int _count;\n\n        public void Increment()\n        {\n            // near-miss: the required Pause() lands BETWEEN the plain read\n            // and the plain write \u2014 every concurrent caller reads the same\n            // stale value and updates vanish by the hundreds\n            int v = _count;\n            CjConcurrency.Pause();\n            _count = v + 1;\n        }\n\n        public int Value => _count;\n\n        public int Drain()\n        {\n            int v = _count;\n            _count = 0;\n            return v;\n        }\n    }\n}\n";
R["csi-p10-bounded-channel"] = "public class Solution\n{\n    public sealed class BoundedChannel\n    {\n        private readonly int _capacity;\n        private readonly System.Collections.Generic.Queue<string> _items = new();\n\n        public BoundedChannel(int capacity) => _capacity = capacity;\n\n        public bool TryProduce(string item)\n        {\n            if (_items.Count >= _capacity) return false;\n            _items.Enqueue(item);\n            return true;\n        }\n\n        public string? TryConsume()\n        {\n            if (_items.Count == 0) return null;\n            return _items.Dequeue();\n        }\n\n        public int Count => _items.Count;\n    }\n}\n";
W["csi-p10-bounded-channel"] = "public class Solution\n{\n    public sealed class BoundedChannel\n    {\n        private readonly System.Collections.Generic.List<string> _items = new();\n\n        public BoundedChannel(int capacity) { }\n\n        // near-miss: capacity accepted but never enforced \u2014 the 4th produce\n        // into a 3-slot channel succeeds and the capacity test fails\n        public bool TryProduce(string item)\n        {\n            _items.Add(item);\n            return true;\n        }\n\n        public string? TryConsume()\n        {\n            if (_items.Count == 0) return null;\n            var first = _items[0];\n            _items.RemoveAt(0);\n            return first;\n        }\n\n        public int Count => _items.Count;\n    }\n}\n";
R["csi-p10-deadlock-debug"] = "public class Solution\n{\n    public sealed class Account\n    {\n        public int Id;\n        public int Balance;\n    }\n\n    public static void Transfer(Account from, Account to, int amount)\n    {\n        // fixed: global lock order \u2014 lower Id first \u2014 makes the cycle impossible\n        var first = from.Id < to.Id ? from : to;\n        var second = from.Id < to.Id ? to : from;\n        lock (first)\n        {\n            CjConcurrency.Pause();   // simulated FX check, still honored\n            lock (second)\n            {\n                if (from.Balance < amount)\n                    throw new System.InvalidOperationException(\"insufficient funds\");\n                from.Balance -= amount;\n                to.Balance += amount;\n            }\n        }\n    }\n}\n";
W["csi-p10-deadlock-debug"] = "public class Solution\n{\n    public sealed class Account\n    {\n        public int Id;\n        public int Balance;\n    }\n\n    public static void Transfer(Account from, Account to, int amount)\n    {\n        // near-miss: always locks \"from\" then \"to\" \u2014 with opposite-direction\n        // transfers each thread holds its first lock, sits in Pause(), and\n        // waits forever on the other's lock (circular wait = deadlock)\n        lock (from)\n        {\n            CjConcurrency.Pause();\n            lock (to)\n            {\n                from.Balance -= amount;\n                to.Balance += amount;\n            }\n        }\n    }\n}\n";
R["csi-p10-visitor-stats"] = "public class Solution\n{\n    public sealed class VisitorStats\n    {\n        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> _counts = new();\n\n        public int RecordVisit(string path)\n        {\n            return _counts.AddOrUpdate(path, 1, (key, old) => old + 1);\n        }\n\n        public int Visits(string path)\n        {\n            return _counts.TryGetValue(path, out int v) ? v : 0;\n        }\n    }\n}\n";
W["csi-p10-visitor-stats"] = "public class Solution\n{\n    public sealed class VisitorStats\n    {\n        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> _counts = new();\n\n        public int RecordVisit(string path)\n        {\n            // near-miss: returns the count BEFORE the increment \u2014 the classic\n            // read-modify-write return bug; the first-visit test expects 1\n            _counts.AddOrUpdate(path, 1, (key, old) => old + 1);\n            return _counts.TryGetValue(path, out int v) ? v - 1 : 0;\n        }\n\n        public int Visits(string path)\n        {\n            return _counts.TryGetValue(path, out int v) ? v : 0;\n        }\n    }\n}\n";
R["csi-checkpoint-m10-task"] = "public class Solution\n{\n    public sealed class JobQueue\n    {\n        private readonly object _gate = new();\n        private readonly System.Collections.Generic.Queue<string> _jobs = new();\n        private readonly System.Collections.Generic.List<string> _results = new();\n\n        public System.Collections.Generic.List<string> Results => _results;\n\n        public void Enqueue(string job)\n        {\n            lock (_gate) { _jobs.Enqueue(job); }\n        }\n\n        public System.Collections.Generic.List<string> RunAll(int workers)\n        {\n            var threads = new System.Collections.Generic.List<System.Threading.Thread>();\n            for (int w = 0; w < workers; w++)\n            {\n                var t = new System.Threading.Thread(Work);\n                t.IsBackground = true;\n                threads.Add(t);\n                t.Start();\n            }\n            foreach (var t in threads) t.Join(30000);\n            return _results;\n        }\n\n        private void Work()\n        {\n            while (true)\n            {\n                string job;\n                lock (_gate)                    // whole check-and-act is atomic\n                {\n                    if (_jobs.Count == 0) return;\n                    job = _jobs.Dequeue();\n                }\n                CjConcurrency.Pause();          // simulated work, OUTSIDE the lock\n                lock (_gate) { _results.Add(\"done:\" + job); }\n            }\n        }\n    }\n}\n";
W["csi-checkpoint-m10-task"] = "public class Solution\n{\n    public sealed class JobQueue\n    {\n        private readonly object _gate = new();\n        private readonly System.Collections.Generic.Queue<string> _jobs = new();\n        private readonly System.Collections.Generic.List<string> _results = new();\n\n        public System.Collections.Generic.List<string> Results => _results;\n\n        public void Enqueue(string job)\n        {\n            lock (_gate) { _jobs.Enqueue(job); }\n        }\n\n        public System.Collections.Generic.List<string> RunAll(int workers)\n        {\n            var threads = new System.Collections.Generic.List<System.Threading.Thread>();\n            for (int w = 0; w < workers; w++)\n            {\n                var t = new System.Threading.Thread(Work);\n                t.IsBackground = true;\n                threads.Add(t);\n                t.Start();\n            }\n            foreach (var t in threads) t.Join(30000);\n            return _results;\n        }\n\n        private void Work()\n        {\n            while (true)\n            {\n                string? job = null;\n                if (_jobs.Count > 0)            // near-miss: check OUTSIDE the lock\n                    job = _jobs.Dequeue();      // two workers dequeue the same job / throw\n                if (job == null) return;\n                CjConcurrency.Pause();\n                lock (_gate) { _results.Add(\"done:\" + job); }\n            }\n        }\n    }\n}\n";
