R["csi-p10-visitor-stats"] = "public class Solution\n{\n    public sealed class VisitorStats\n    {\n        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> _counts = new();\n\n        public int RecordVisit(string path)\n        {\n            return _counts.AddOrUpdate(path, 1, (key, old) => old + 1);\n        }\n\n        public int Visits(string path)\n        {\n            return _counts.TryGetValue(path, out int v) ? v : 0;\n        }\n    }\n}\n";
W["csi-p10-visitor-stats"] = "public class Solution\n{\n    public sealed class VisitorStats\n    {\n        private readonly System.Collections.Concurrent.ConcurrentDictionary<string, int> _counts = new();\n\n        public int RecordVisit(string path)\n        {\n            // near-miss: returns the count BEFORE the increment \u2014 the classic\n            // read-modify-write return bug; the first-visit test expects 1\n            _counts.AddOrUpdate(path, 1, (key, old) => old + 1);\n            return _counts.TryGetValue(path, out int v) ? v - 1 : 0;\n        }\n\n        public int Visits(string path)\n        {\n            return _counts.TryGetValue(path, out int v) ? v : 0;\n        }\n    }\n}\n";
R["csi-checkpoint-m10-task"] = "public class Solution\n{\n    public sealed class JobQueue\n    {\n        private readonly object _gate = new();\n        private readonly System.Collections.Generic.Queue<string> _jobs = new();\n        private readonly System.Collections.Generic.List<string> _results = new();\n\n        public System.Collections.Generic.List<string> Results => _results;\n\n        public void Enqueue(string job)\n        {\n            lock (_gate) { _jobs.Enqueue(job); }\n        }\n\n        public System.Collections.Generic.List<string> RunAll(int workers)\n        {\n            var threads = new System.Collections.Generic.List<System.Threading.Thread>();\n            for (int w = 0; w < workers; w++)\n            {\n                var t = new System.Threading.Thread(Work);\n                t.IsBackground = true;\n                threads.Add(t);\n                t.Start();\n            }\n            foreach (var t in threads) t.Join(30000);\n            return _results;\n        }\n\n        private void Work()\n        {\n            while (true)\n            {\n                string job;\n                lock (_gate)                    // whole check-and-act is atomic\n                {\n                    if (_jobs.Count == 0) return;\n                    job = _jobs.Dequeue();\n                }\n                CjConcurrency.Pause();          // simulated work, OUTSIDE the lock\n                lock (_gate) { _results.Add(\"done:\" + job); }\n            }\n        }\n    }\n}\n";
W["csi-checkpoint-m10-task"] = "public class Solution\n{\n    public sealed class JobQueue\n    {\n        private readonly object _gate = new();\n        private readonly System.Collections.Generic.Queue<string> _jobs = new();\n        private readonly System.Collections.Generic.List<string> _results = new();\n\n        public System.Collections.Generic.List<string> Results => _results;\n\n        public void Enqueue(string job)\n        {\n            lock (_gate) { _jobs.Enqueue(job); }\n        }\n\n        public System.Collections.Generic.List<string> RunAll(int workers)\n        {\n            var threads = new System.Collections.Generic.List<System.Threading.Thread>();\n            for (int w = 0; w < workers; w++)\n            {\n                var t = new System.Threading.Thread(Work);\n                t.IsBackground = true;\n                threads.Add(t);\n                t.Start();\n            }\n            // near-miss: workers started but NEVER JOINED \u2014 RunAll returns\n            // immediately, before any worker has processed anything; the\n            // caller sees zero results and no completion guarantee\n            return _results;\n        }\n\n        private void Work()\n        {\n            while (true)\n            {\n                string job;\n                lock (_gate)\n                {\n                    if (_jobs.Count == 0) return;\n                    job = _jobs.Dequeue();\n                }\n                CjConcurrency.Pause();\n                lock (_gate) { _results.Add(\"done:\" + job); }\n            }\n        }\n    }\n}\n";
