R["csi-checkpoint-m11-task"] = "public class Solution\n{\n    public record Order(int Id, decimal Amount);\n\n    public interface IOrderValidator\n    {\n        bool IsValid(decimal amount);\n    }\n\n    public sealed class PositiveAmountValidator : IOrderValidator\n    {\n        public bool IsValid(decimal amount) => amount > 0;\n    }\n\n    public interface IOrderRepository\n    {\n        Order Save(Order order);\n    }\n\n    public sealed class MemoryRepo : IOrderRepository\n    {\n        private int _nextId = 1;\n        public System.Collections.Generic.List<Order> Saved { get; } = new();\n\n        public Order Save(Order order)\n        {\n            var saved = order with { Id = _nextId++ };\n            Saved.Add(saved);\n            return saved;\n        }\n    }\n\n    public interface IAuditLog\n    {\n        void Record(string message);\n    }\n\n    public sealed class MemoryAudit : IAuditLog\n    {\n        public System.Collections.Generic.List<string> Entries { get; } = new();\n\n        public void Record(string message) => Entries.Add(message);\n    }\n\n    public sealed class OrderProcessor\n    {\n        private readonly IOrderValidator _validator;\n        private readonly IOrderRepository _repo;\n        private readonly IAuditLog _audit;\n\n        public OrderProcessor(IOrderValidator validator, IOrderRepository repo, IAuditLog audit)\n        {\n            _validator = validator;\n            _repo = repo;\n            _audit = audit;\n        }\n\n        public string Process(decimal amount)\n        {\n            if (!_validator.IsValid(amount)) return \"rejected\";\n            var saved = _repo.Save(new Order(0, amount));\n            _audit.Record(\"order \" + saved.Id + \" amount \" + saved.Amount);\n            return \"ok:\" + saved.Id;\n        }\n    }\n\n    public static OrderProcessor BuildProcessor(IOrderRepository repo, IAuditLog audit)\n    {\n        var container = new TinyContainer();\n        container.RegisterSingleton<IOrderValidator>(() => new PositiveAmountValidator());\n        container.RegisterTransient<OrderProcessor>(() => new OrderProcessor(\n            container.Resolve<IOrderValidator>(), repo, audit));\n        return container.Resolve<OrderProcessor>();\n    }\n}\n";
W["csi-checkpoint-m11-task"] = "public class Solution\n{\n    public record Order(int Id, decimal Amount);\n\n    public interface IOrderValidator\n    {\n        bool IsValid(decimal amount);\n    }\n\n    public sealed class PositiveAmountValidator : IOrderValidator\n    {\n        public bool IsValid(decimal amount) => amount > 0;\n    }\n\n    public interface IOrderRepository\n    {\n        Order Save(Order order);\n    }\n\n    public sealed class MemoryRepo : IOrderRepository\n    {\n        private int _nextId = 1;\n        public System.Collections.Generic.List<Order> Saved { get; } = new();\n\n        public Order Save(Order order)\n        {\n            var saved = order with { Id = _nextId++ };\n            Saved.Add(saved);\n            return saved;\n        }\n    }\n\n    public interface IAuditLog\n    {\n        void Record(string message);\n    }\n\n    public sealed class MemoryAudit : IAuditLog\n    {\n        public System.Collections.Generic.List<string> Entries { get; } = new();\n\n        public void Record(string message) => Entries.Add(message);\n    }\n\n    public sealed class OrderProcessor\n    {\n        private readonly IOrderValidator _validator;\n        private readonly IOrderRepository _repo;\n        private readonly IAuditLog _audit;\n\n        public OrderProcessor(IOrderValidator validator, IOrderRepository repo, IAuditLog audit)\n        {\n            _validator = validator;\n            _repo = repo;\n            _audit = audit;\n        }\n\n        public string Process(decimal amount)\n        {\n            if (!_validator.IsValid(amount)) return \"rejected\";\n            var saved = _repo.Save(new Order(0, amount));\n            _audit.Record(\"order \" + saved.Id + \" amount \" + saved.Amount);\n            return \"ok:\" + saved.Id;\n        }\n    }\n\n    public static OrderProcessor BuildProcessor(IOrderRepository repo, IAuditLog audit)\n    {\n        // near-miss: registers the PROCESSOR as singleton keyed by the\n        // VALIDATOR type \u2014 Resolve<IOrderValidator> returns the processor\n        // cast, Resolve<OrderProcessor> is unregistered and throws; the\n        // BuildProcessor call fails outright\n        var container = new TinyContainer();\n        container.RegisterSingleton<IOrderValidator>(() => new PositiveAmountValidator());\n        container.RegisterSingleton<OrderProcessor>(() => new OrderProcessor(\n            new PositiveAmountValidator(), repo, audit));\n        container.RegisterTransient<OrderProcessor>(() =>\n            (OrderProcessor)container.Resolve<IOrderValidator>());\n        return container.Resolve<OrderProcessor>();\n    }\n}\n";
