W["csi-p12-env-provider"] = "public class Solution\n{\n    public sealed class EnvConfig\n    {\n        private readonly string _prefix;\n\n        public EnvConfig(string prefix) => _prefix = prefix;\n\n        public string? Get(string name)\n        {\n            return System.Environment.GetEnvironmentVariable(_prefix + \"_\" + name);   // near-miss: single underscore \u2014 the CJ__REGION convention never matches\n        }\n\n        public int GetInt(string name)\n        {\n            string? raw = Get(name);\n            if (raw is null) return 0;   // near-miss: silently converts missing config to 0\n            return int.Parse(raw);\n        }\n    }\n}\n";
R["csi-p12-options-binding"] = "public class Solution\n{\n    public sealed class RetryOptions\n    {\n        public int MaxAttempts { get; set; } = 3;\n        public int DelayMs { get; set; } = 200;\n    }\n\n    public sealed class OptionsBinder\n    {\n        public static RetryOptions Bind(string json)\n        {\n            var options = new RetryOptions();\n            using var doc = System.Text.Json.JsonDocument.Parse(json);\n            if (doc.RootElement.TryGetProperty(\"Retry\", out var section))\n            {\n                if (section.TryGetProperty(\"MaxAttempts\", out var ma))\n                    options.MaxAttempts = ma.GetInt32();\n                if (section.TryGetProperty(\"DelayMs\", out var dm))\n                    options.DelayMs = dm.GetInt32();\n            }\n            return options;\n        }\n\n        public static void Validate(RetryOptions options)\n        {\n            var problems = new System.Collections.Generic.List<string>();\n            if (options.MaxAttempts < 1) problems.Add(\"MaxAttempts must be >= 1\");\n            if (options.DelayMs < 0) problems.Add(\"DelayMs must be >= 0\");\n            if (problems.Count > 0)\n                throw new System.InvalidOperationException(\"Retry: \" + string.Join(\"; \", problems));\n        }\n    }\n}\n";
W["csi-p12-options-binding"] = "public class Solution\n{\n    public sealed class RetryOptions\n    {\n        public int MaxAttempts { get; set; } = 3;\n        public int DelayMs { get; set; } = 200;\n    }\n\n    public sealed class OptionsBinder\n    {\n        public static RetryOptions Bind(string json)\n        {\n            // near-miss: GetProperty throws KeyNotFoundException when the\n            // section or a key is absent \u2014 the defaults-kept test never runs\n            var options = new RetryOptions();\n            using var doc = System.Text.Json.JsonDocument.Parse(json);\n            var section = doc.RootElement.GetProperty(\"Retry\");\n            options.MaxAttempts = section.GetProperty(\"MaxAttempts\").GetInt32();\n            options.DelayMs = section.GetProperty(\"DelayMs\").GetInt32();\n            return options;\n        }\n\n        public static void Validate(RetryOptions options)\n        {\n            // near-miss: throws on the FIRST violation only \u2014 the message\n            // never contains both keys when both are broken\n            if (options.MaxAttempts < 1)\n                throw new System.InvalidOperationException(\"Retry: MaxAttempts must be >= 1\");\n            if (options.DelayMs < 0)\n                throw new System.InvalidOperationException(\"Retry: DelayMs must be >= 0\");\n        }\n    }\n}\n";
R["csi-p12-secrets-debug"] = "public class Solution\n{\n    public interface IConfigProvider\n    {\n        string? Get(string key);\n    }\n\n    public sealed class MemoryConfig : IConfigProvider\n    {\n        private readonly System.Collections.Generic.Dictionary<string, string> _entries = new();\n\n        public MemoryConfig(params (string Key, string Value)[] entries)\n        {\n            foreach (var (key, value) in entries) _entries[key] = value;\n        }\n\n        public string? Get(string key) => _entries.TryGetValue(key, out var v) ? v : null;\n    }\n\n    public sealed class ReportSender\n    {\n        private readonly IConfigProvider _config;\n\n        public ReportSender(IConfigProvider config) => _config = config;\n\n        public string Send(string report)\n        {\n            string? key = _config.Get(\"ApiKey\");\n            if (string.IsNullOrEmpty(key))\n                throw new System.InvalidOperationException(\"ApiKey is not configured\");\n            return \"sent:\" + key + \":\" + report.Length;\n        }\n    }\n}\n";
W["csi-p12-secrets-debug"] = "public class Solution\n{\n    public interface IConfigProvider\n    {\n        string? Get(string key);\n    }\n\n    public sealed class MemoryConfig : IConfigProvider\n    {\n        private readonly System.Collections.Generic.Dictionary<string, string> _entries = new();\n\n        public MemoryConfig(params (string Key, string Value)[] entries)\n        {\n            foreach (var (key, value) in entries) _entries[key] = value;\n        }\n\n        public string? Get(string key) => _entries.TryGetValue(key, out var v) ? v : null;\n    }\n\n    public sealed class ReportSender\n    {\n        private readonly IConfigProvider _config;\n\n        public ReportSender(IConfigProvider config) => _config = config;\n\n        public string Send(string report)\n        {\n            // near-miss: hardcoded fallback credential ships a \"real-looking\"\n            // key to every environment and hides the missing configuration\n            string key = _config.Get(\"ApiKey\") ?? \"sk-dev-fallback-123\";\n            return \"sent:\" + key + \":\" + report.Length;\n        }\n    }\n}\n";
R["csi-checkpoint-m12-task"] = "public class Solution\n{\n    public interface IConfigProvider\n    {\n        string? Get(string key);\n    }\n\n    public sealed class MemoryConfig : IConfigProvider\n    {\n        private readonly System.Collections.Generic.Dictionary<string, string> _entries = new();\n\n        public MemoryConfig(params (string Key, string Value)[] entries)\n        {\n            foreach (var (key, value) in entries) _entries[key] = value;\n        }\n\n        public string? Get(string key) => _entries.TryGetValue(key, out var v) ? v : null;\n    }\n\n    public sealed class RetryOptions\n    {\n        public int MaxAttempts { get; set; } = 3;\n        public int DelayMs { get; set; } = 200;\n    }\n\n    public static string? GetJson(string json, string key)\n    {\n        using var doc = System.Text.Json.JsonDocument.Parse(json);\n        var node = doc.RootElement;\n        foreach (string part in key.Split(':'))\n        {\n            if (node.ValueKind != System.Text.Json.JsonValueKind.Object ||\n                !node.TryGetProperty(part, out node))\n                return null;\n        }\n        return node.ToString();\n    }\n\n    public static string? GetLayered(IConfigProvider file, string envPrefix, string key)\n    {\n        string envKey = envPrefix + \"__\" + key.ToUpperInvariant().Replace(':', '_');\n        string? fromEnv = System.Environment.GetEnvironmentVariable(envKey);\n        if (fromEnv is not null) return fromEnv;\n        return file.Get(key);\n    }\n\n    public static RetryOptions BindRetry(IConfigProvider config)\n    {\n        var options = new RetryOptions();\n        string? ma = config.Get(\"Retry:MaxAttempts\");\n        if (ma is not null) options.MaxAttempts = int.Parse(ma);\n        string? dm = config.Get(\"Retry:DelayMs\");\n        if (dm is not null) options.DelayMs = int.Parse(dm);\n        return options;\n    }\n\n    public static void Validate(RetryOptions options)\n    {\n        var problems = new System.Collections.Generic.List<string>();\n        if (options.MaxAttempts < 1) problems.Add(\"MaxAttempts must be >= 1\");\n        if (options.DelayMs < 0) problems.Add(\"DelayMs must be >= 0\");\n        if (problems.Count > 0)\n            throw new System.InvalidOperationException(\"Retry: \" + string.Join(\"; \", problems));\n    }\n\n    public static string Require(IConfigProvider config, string key)\n    {\n        string? value = config.Get(key);\n        if (string.IsNullOrEmpty(value))\n            throw new System.InvalidOperationException(\"Configuration key \" + key + \" is required\");\n        return value;\n    }\n}\n";
