R["csi-checkpoint-m13-task"] = "public class Solution\n{\n    public sealed class ApiClient\n    {\n        private readonly System.Net.Http.HttpClient _http;\n\n        public ApiClient(System.Net.Http.HttpClient http) => _http = http;\n\n        public async System.Threading.Tasks.Task<string> GetUserAsync(\n            int id, System.Threading.CancellationToken ct = default)\n        {\n            ct.ThrowIfCancellationRequested();\n            using var resp = await _http.GetAsync(\"/users/\" + id, ct);\n            int code = (int)resp.StatusCode;\n            if (code == 200)\n            {\n                string body = await resp.Content.ReadAsStringAsync(ct);\n                int i = body.IndexOf(\"\\\"name\\\":\\\"\") + 7;\n                int j = body.IndexOf('\"', i);\n                return \"user:\" + body.Substring(i, j - i);\n            }\n            if (code == 404) return \"notfound\";\n            return \"failed\";\n        }\n\n        public async System.Threading.Tasks.Task<string> GetUserWithRetryAsync(\n            int id, int maxAttempts, System.Threading.CancellationToken ct = default)\n        {\n            for (int attempt = 1; ; attempt++)\n            {\n                ct.ThrowIfCancellationRequested();\n                using var resp = await _http.GetAsync(\"/users/\" + id, ct);\n                int code = (int)resp.StatusCode;\n                if (code == 200)\n                {\n                    string body = await resp.Content.ReadAsStringAsync(ct);\n                    int i = body.IndexOf(\"\\\"name\\\":\\\"\") + 7;\n                    int j = body.IndexOf('\"', i);\n                    return \"user:\" + body.Substring(i, j - i);\n                }\n                if (code == 404) return \"notfound\";\n                if (code < 500 || attempt >= maxAttempts) return \"failed\";\n                await CjStubHandler.DelayAsync(\n                    System.Math.Min(10 << (attempt - 1), 50), ct);\n            }\n        }\n    }\n}\n";
