R["csi-p13-retry-backoff"] = "public class Solution\n{\n    public static async System.Threading.Tasks.Task<string> GetWithRetryAsync(\n        System.Net.Http.HttpClient http, string path,\n        int maxAttempts, int baseMs, int capMs,\n        System.Threading.CancellationToken ct = default)\n    {\n        for (int attempt = 1; ; attempt++)\n        {\n            try\n            {\n                using var resp = await http.GetAsync(path, ct);\n                int code = (int)resp.StatusCode;\n                if (resp.IsSuccessStatusCode)\n                    return await resp.Content.ReadAsStringAsync(ct);\n                if (code < 500 || attempt >= maxAttempts)\n                    return \"failed\";\n            }\n            catch (System.Net.Http.HttpRequestException)\n            {\n                if (attempt >= maxAttempts) return \"failed\";\n            }\n            await CjStubHandler.DelayAsync(\n                System.Math.Min(baseMs << (attempt - 1), capMs), ct);\n        }\n    }\n}\n";
