"bad payload\");\n        }\n        catch (System.Text.Json.JsonException ex)\n        {\n            throw new System.InvalidOperationException(\"bad payload\", ex);\n        }\n\n        var items = new System.Collections.Generic.List<Product>();\n        foreach (var p in wrapper.Products)\n        {\n            if (string.IsNullOrEmpty(p.Name))\n                throw new System.InvalidOperationException(\"bad payload\");\n            items.Add(p);\n        }\n        return items;\n    }\n\n    public static string Merge(string jsonA, string jsonB)\n    {\n        var seen = new System.Collections.Generic.HashSet<string>();\n        var merged = new System.Collections.Generic.List<Product>();\n        foreach (var p in Import(jsonA).Concat(Import(jsonB)))\n        {\n            if (seen.Add(p.Name)) merged.Add(p);\n        }\n        return Export(merged);\n    }\n}\n";
