R["csi-p14-numeric-strings"] = "public class Solution\n{\n    public sealed class Payload\n    {\n        public int Count { get; set; }\n    }\n\n    public sealed class FlexibleIntConverter : System.Text.Json.Serialization.JsonConverter<int>\n    {\n        public override int Read(ref System.Text.Json.Utf8JsonReader reader, System.Type typeToConvert, System.Text.Json.JsonSerializerOptions options)\n        {\n            return reader.TokenType switch\n            {\n                System.Text.Json.JsonTokenType.Number => reader.GetInt32(),\n                System.Text.Json.JsonTokenType.String => int.Parse(reader.GetString()!),\n                _ => throw new System.Text.Json.JsonException(),\n            };\n        }\n\n        public override void Write(System.Text.Json.Utf8JsonWriter writer, int value, System.Text.Json.JsonSerializerOptions options)\n        {\n            writer.WriteNumberValue(value);\n        }\n    }\n\n    private static readonly System.Text.Json.JsonSerializerOptions Opts = new()\n    {\n        PropertyNameCaseInsensitive = true,   // external payload: keys may vary in case\n        Converters = { new FlexibleIntConverter() },\n    };\n\n    public static Payload? DeserializePayload(string json) =>\n        System.Text.Json.JsonSerializer.Deserialize<Payload>(json, Opts);\n}\n";
